86:.donate{display:inline-flex;align-items:center;gap:6px;margin-top:6px;padding:6px 10px;border:1px solid rgba(230,189,106,.32);border-radius:4px;color:var(--gold);font:12px var(--font-body);text-decoration:none;}
87:.donate svg{width:14px;height:14px;flex:0 0 auto;}
88:.donate[hidden]{display:none;}
